import java.util.*;
import java.util.function.*;

public class Lam1 {
    record Book(String title, int pages) {}

    interface Validator<T> { boolean test(T t); }

    public static void main(String[] args) {
        // 1. a lambda is an instance of a functional interface
        Validator<String> notBlank = s -> !s.isBlank();
        System.out.println(notBlank.test("Java") + " " + notBlank.test("  "));

        // 2. same lambda text, different target types
        Function<Integer, Integer> inc = x -> x + 1;
        UnaryOperator<Integer> inc2 = x -> x + 1;
        System.out.println(inc.apply(1) + " " + inc2.apply(1));

        // 3. java.util.function family
        Predicate<Book> longBook = b -> b.pages() > 300;
        Function<Book, String> title = Book::title;
        Supplier<List<Book>> fresh = ArrayList::new;
        Consumer<Book> printer = b -> System.out.println("Book: " + b.title());
        BiFunction<String, Integer, Book> make = Book::new;
        BinaryOperator<Integer> add = Integer::sum;
        IntBinaryOperator mul = (a, b) -> a * b;

        List<Book> shelf = fresh.get();
        shelf.add(make.apply("Effective Java", 412));
        shelf.add(make.apply("Java Puzzlers", 312));
        shelf.add(make.apply("Tiny Book", 90));
        shelf.stream().filter(longBook).map(title).forEach(System.out::println);
        printer.accept(shelf.get(2));
        System.out.println(add.apply(2, 3) + " " + mul.applyAsInt(4, 5));

        // 4. composition
        Predicate<Book> shortBook = longBook.negate();
        Function<Integer, Integer> dbl = x -> x * 2;
        System.out.println(shortBook.test(shelf.get(2)));
        System.out.println(inc.andThen(dbl).apply(5) + " " + inc.compose(dbl).apply(5));

        // 5. capture
        int base = 100;                         // effectively final
        Function<Integer, Integer> addBase = x -> x + base;
        System.out.println(addBase.apply(5));
        int[] counter = {0};                    // the box is final, contents mutable
        Runnable r = () -> counter[0]++;
        r.run(); r.run();
        System.out.println(counter[0]);
    }
}

@FunctionalInterface
public interface Retry<T> {
    T attempt() throws Exception;          // checked exceptions are allowed here

    default T withRetries(int times) throws Exception {
        Exception last = null;
        for (int i = 0; i < times; i++) {
            try { return attempt(); } catch (Exception e) { last = e; }
        }
        throw last;
    }
}

