import java.util.*;
import java.util.function.*;

public class Lam2 {
    private final String name = "outer";

    Runnable lambda() {
        return () -> System.out.println("lambda this = " + this.name + " "
            + getClass().getSimpleName());
    }

    Runnable anon() {
        return new Runnable() {
            public void run() { System.out.println("anon this = " + this.getClass().getName()); }
        };
    }

    static String up(String s) { return s.toUpperCase(); }
    String hello(String who) { return "hello " + who; }

    public static void main(String[] args) {
        new Lam2().lambda().run();
        new Lam2().anon().run();

        // four kinds of method reference
        Function<String, String> a = Lam2::up;                 // static
        Lam2 inst = new Lam2();
        Function<String, String> b = inst::hello;              // bound instance
        Function<String, Integer> c = String::length;          // unbound instance
        Supplier<ArrayList<String>> d = ArrayList::new;        // constructor
        Function<Integer, int[]> e = int[]::new;               // array constructor
        System.out.println(a.apply("x") + " " + b.apply("bob") + " " + c.apply("four")
            + " " + d.get() + " " + e.apply(3).length);

        // class names of lambdas
        Runnable r1 = () -> {};
        Runnable r2 = () -> {};
        System.out.println(r1.getClass().isSynthetic() + " "
            + r1.getClass().getName().contains("$$Lambda"));
        System.out.println(r1.getClass() == r2.getClass());
        System.out.println(r1.getClass().getInterfaces()[0].getSimpleName());

        // non-capturing lambda evaluated twice yields the same instance
        System.out.println(sup() == sup());
        int k = 1;
        System.out.println(cap(k) == cap(k));
    }
    static Supplier<String> sup() { return () -> "x"; }
    static Supplier<Integer> cap(int k) { return () -> k; }
}

