import java.util.*;

public class Opt1 {
    record Member(String name, String email) {}

    static final Map<Integer, Member> DB = Map.of(
        1, new Member("Asha", "asha@example.com"),
        2, new Member("Ben", null));

    static Optional<Member> find(int id) { return Optional.ofNullable(DB.get(id)); }

    static String expensiveDefault() {
        System.out.println("  (computing default)");
        return "none@example.com";
    }

    public static void main(String[] args) {
        // creation
        Optional<String> e = Optional.empty();
        Optional<String> p = Optional.of("x");
        Optional<String> n = Optional.ofNullable(null);
        System.out.println(e + " " + p + " " + n);
        try { Optional.of(null); }
        catch (NullPointerException ex) { System.out.println("of(null) -> NPE"); }

        // map / flatMap / filter
        for (int id : new int[]{1, 2, 3}) {
            String mail = find(id)
                .map(Member::email)              // map: null result becomes empty
                .filter(s -> s.endsWith(".com"))
                .orElse("(no email)");
            System.out.println(id + " -> " + mail);
        }

        // orElse vs orElseGet
        System.out.println("orElse:");
        System.out.println(find(1).map(Member::email).orElse(expensiveDefault()));
        System.out.println("orElseGet:");
        System.out.println(find(1).map(Member::email).orElseGet(Opt1::expensiveDefault));

        // orElseThrow, ifPresentOrElse, or, stream
        try { find(3).orElseThrow(() -> new NoSuchElementException("member 3")); }
        catch (NoSuchElementException ex) { System.out.println("thrown: " + ex.getMessage()); }
        find(2).ifPresentOrElse(m -> System.out.println("found " + m.name()),
                                () -> System.out.println("absent"));
        System.out.println(find(3).or(() -> find(1)).map(Member::name).get());
        System.out.println(java.util.stream.Stream.of(1, 2, 3).map(Opt1::find)
            .flatMap(Optional::stream).map(Member::name).toList());

        // flatMap
        Optional<Optional<String>> nested = find(1).map(m -> Optional.ofNullable(m.email()));
        Optional<String> flat = find(1).flatMap(m -> Optional.ofNullable(m.email()));
        System.out.println(nested + " | " + flat);

        // primitives
        OptionalInt max = java.util.stream.IntStream.of(3, 9, 4).max();
        System.out.println(max + " " + max.getAsInt() + " "
            + java.util.stream.IntStream.empty().max());
        OptionalDouble avg = java.util.stream.IntStream.empty().average();
        System.out.println(avg.orElse(-1));
        // equality
        System.out.println(Optional.of("a").equals(Optional.of("a")));
        try { e.get(); } catch (NoSuchElementException ex) { System.out.println(ex.getMessage()); }
    }
}

