import java.util.*;
import java.util.stream.*;

public class Str1 {
    public static void main(String[] args) {
        List<String> names = List.of("kiwi", "apple", "fig", "banana", "cherry", "date");

        // 1. nothing runs until the terminal operation
        Stream<String> pipeline = names.stream()
            .peek(s -> System.out.println("  peek1 " + s))
            .filter(s -> s.length() > 3)
            .peek(s -> System.out.println("  peek2 " + s))
            .map(String::toUpperCase);
        System.out.println("pipeline built, nothing printed yet");
        List<String> out = pipeline.limit(2).toList();
        System.out.println(out);

        // 2. one-shot
        Stream<String> s = names.stream();
        s.count();
        try { s.count(); } catch (IllegalStateException e) { System.out.println(e.getMessage()); }

        // 3. sources
        System.out.println(IntStream.rangeClosed(1, 5).boxed().toList());
        System.out.println(Stream.iterate(1, x -> x * 2).limit(8).toList());
        System.out.println(Stream.iterate(1, x -> x < 100, x -> x * 3).toList());
        System.out.println(Arrays.stream(new int[]{4, 5, 6}).sum());
        System.out.println("a-b-c".chars().filter(Character::isLetter).count());
        System.out.println(Stream.of("x", "y").collect(Collectors.joining("+")));

        // 4. flatMap and mapMulti
        List<List<Integer>> nested = List.of(List.of(1, 2), List.of(), List.of(3));
        System.out.println(nested.stream().flatMap(List::stream).toList());
        System.out.println(Stream.of(1, 2, 3).<Integer>mapMulti((x, sink) -> {
            if (x != 2) { sink.accept(x); sink.accept(x * 10); }
        }).toList());

        // 5. takeWhile / dropWhile (ordered)
        System.out.println(Stream.of(1, 2, 3, 10, 1, 2).takeWhile(x -> x < 5).toList());
        System.out.println(Stream.of(1, 2, 3, 10, 1, 2).dropWhile(x -> x < 5).toList());

        // 6. stateful: sorted, distinct
        System.out.println(names.stream().sorted(Comparator.comparing(String::length)
            .thenComparing(Comparator.naturalOrder())).toList());
        System.out.println(Stream.of(3, 1, 3, 2, 1).distinct().toList());

        // 7. reduce and terminal ops
        System.out.println(Stream.of(1, 2, 3, 4).reduce(0, Integer::sum));
        System.out.println(Stream.of(1, 2, 3, 4).reduce(Integer::max));
        System.out.println(names.stream().anyMatch(x -> x.startsWith("f")));
        System.out.println(names.stream().allMatch(x -> x.length() > 3));
        System.out.println(names.stream().noneMatch(String::isEmpty));
        System.out.println(names.stream().filter(x -> x.length() == 6).findFirst());
        System.out.println(IntStream.of(4, 8, 15).summaryStatistics());
        System.out.println(IntStream.range(0, 5).mapToObj(i -> "i" + i)
            .collect(Collectors.joining(",", "[", "]")));
        System.out.println(names.stream().mapToInt(String::length).average().getAsDouble());

        // 8. toList() is unmodifiable; collect(toList()) is not guaranteed either way
        List<String> t = names.stream().toList();
        try { t.add("x"); }
        catch (UnsupportedOperationException e) { System.out.println("toList: unmodifiable"); }
    }
}

import java.util.*;
import java.util.stream.*;

public class Str2 {
    public static void main(String[] args) {
        // short-circuit visits
        Stream.of("a", "b", "c", "d").peek(x -> System.out.println("visit " + x))
              .filter(x -> x.compareTo("b") >= 0).findFirst().ifPresent(System.out::println);

        // sorted is a barrier
        Stream.of(3, 1, 2).peek(x -> System.out.println("before sort " + x)).sorted()
              .peek(x -> System.out.println("after sort " + x)).limit(1).forEach(x -> {});

        // vertical processing
        Stream.of("a", "b").peek(x -> System.out.println("p1 " + x)).map(String::toUpperCase)
              .forEach(x -> System.out.println("p2 " + x));

        // interference: modifying the source during the pipeline
        List<Integer> src = new ArrayList<>(List.of(1, 2, 3));
        try { src.stream().forEach(x -> { if (x == 2) src.add(99); }); }
        catch (ConcurrentModificationException e) { System.out.println("CME"); }

        // stateful lambda: wrong
        List<Integer> sink = new ArrayList<>();
        IntStream.range(0, 5).forEach(sink::add);
        System.out.println(sink);
        // unordered source: HashSet
        TreeSet<Integer> sorted = Stream.of(5, 3, 8)
            .collect(Collectors.toCollection(TreeSet::new));
        System.out.println(sorted);
        // infinite stream with limit
        System.out.println(Stream.generate(() -> "z").limit(3).collect(Collectors.joining()));
        // reduce with identity and combiner
        System.out.println(Stream.of("a", "bb", "ccc")
            .reduce(0, (acc, s) -> acc + s.length(), Integer::sum));
        // primitive boxed
        System.out.println(IntStream.rangeClosed(1, 5).mapToObj(Integer::toString)
            .collect(Collectors.joining("*")));
        System.out.println(LongStream.rangeClosed(1, 20).reduce(1L, (a, b) -> a * b));
    }
}

import java.util.*;
import java.util.stream.*;

public class Col1 {
    enum Category { FICTION, SCIENCE, HISTORY }
    record Book(String title, String author, Category cat, int pages, double price) {}

    static void show(Object o) { System.out.println(o); }

    public static void main(String[] args) {
        List<Book> books = List.of(
            new Book("Dune", "Herbert", Category.FICTION, 612, 12.5),
            new Book("Emma", "Austen", Category.FICTION, 474, 8.0),
            new Book("Cosmos", "Sagan", Category.SCIENCE, 396, 15.0),
            new Book("Origin", "Darwin", Category.SCIENCE, 502, 11.0),
            new Book("SPQR", "Beard", Category.HISTORY, 608, 18.0),
            new Book("Persuasion", "Austen", Category.FICTION, 249, 7.5));

        // groupingBy: classifier only -> Map<K, List<T>>
        Map<Category, List<String>> titlesByCat = books.stream().collect(
            Collectors.groupingBy(Book::cat, TreeMap::new,
                Collectors.mapping(Book::title, Collectors.toList())));
        show(titlesByCat);
        // downstream collectors
        show(books.stream().collect(
            Collectors.groupingBy(Book::cat, TreeMap::new, Collectors.counting())));
        show(books.stream().collect(
            Collectors.groupingBy(Book::cat, TreeMap::new, Collectors.averagingInt(Book::pages))));
        Map<Category, Optional<Book>> priciest = books.stream().collect(
            Collectors.groupingBy(Book::cat, TreeMap::new,
                Collectors.maxBy(Comparator.comparingDouble(Book::price))));
        show(priciest.get(Category.FICTION).map(Book::title).orElse("?"));

        // partitioningBy: always two keys
        Map<Boolean, Long> longVsShort = books.stream()
            .collect(Collectors.partitioningBy(b -> b.pages() > 450, Collectors.counting()));
        show(longVsShort);

        // joining
        show(books.stream().map(Book::title).sorted()
            .collect(Collectors.joining(", ", "{", "}")));

        // summarizing
        DoubleSummaryStatistics st = books.stream()
            .collect(Collectors.summarizingDouble(Book::price));
        System.out.printf("min=%.1f max=%.1f avg=%.2f sum=%.1f n=%d%n",
            st.getMin(), st.getMax(), st.getAverage(), st.getSum(), st.getCount());

        // toMap and its duplicate-key pitfall
        try {
            books.stream().collect(Collectors.toMap(Book::author, Book::title));
        } catch (IllegalStateException e) { show(e.getMessage()); }
        Map<String, String> merged = books.stream().collect(
            Collectors.toMap(Book::author, Book::title, (a, b) -> a + "|" + b, TreeMap::new));
        show(merged);

        // teeing: two collectors, one pass
        var minMax = books.stream().collect(Collectors.teeing(
            Collectors.minBy(Comparator.comparingInt(Book::pages)),
            Collectors.maxBy(Comparator.comparingInt(Book::pages)),
            (mn, mx) -> mn.get().title() + ".." + mx.get().title()));
        show(minMax);

        // collectingAndThen, toUnmodifiableList, filtering, flatMapping
        List<String> frozen = books.stream().map(Book::author).distinct()
            .collect(Collectors.collectingAndThen(Collectors.toList(),
                                                  Collections::unmodifiableList));
        show(frozen);
        show(books.stream().collect(
            Collectors.groupingBy(Book::cat, TreeMap::new,
                Collectors.filtering(b -> b.price() > 10, Collectors.counting()))));

        // groupingBy produces HashMap (order unspecified) unless you pass a factory
        Map<String, Integer> pagesByAuthor = books.stream().collect(
            Collectors.groupingBy(Book::author, TreeMap::new, Collectors.summingInt(Book::pages)));
        show(pagesByAuthor);
    }
}

