public class GatherDemo {
    public static void main(String[] args) {
        // batches of three (e.g. for bulk inserts): [[1, 2, 3], [4, 5, 6], [7, 8]]
        System.out.println(Stream.of(1, 2, 3, 4, 5, 6, 7, 8)
            .gather(Gatherers.windowFixed(3)).toList());

        // moving window: [[1, 2], [2, 3], [3, 4], ...]
        System.out.println(Stream.of(1, 2, 3, 4, 5)
            .gather(Gatherers.windowSliding(2)).toList());

        // running totals: [1, 3, 6, 10, 15]
        System.out.println(Stream.of(1, 2, 3, 4, 5)
            .gather(Gatherers.scan(() -> 0, Integer::sum)).toList());

        // fold emits exactly one element: Optional["12345"]
        System.out.println(Stream.of(1, 2, 3, 4, 5)
            .gather(Gatherers.fold(() -> "", (s, n) -> s + n)).findFirst());
    }
}

import java.util.List;
import java.util.Objects;
import java.util.stream.Gatherer;
import java.util.stream.Stream;

public class Dedupe {
    /** Drops an element when it equals the one just before it. */
    static <T> Gatherer<T, ?, T> dropConsecutiveDuplicates() {
        class Last { T value; boolean seen; }          // private state for one run

        return Gatherer.<T, Last, T>ofSequential(
            Last::new,                                  // initializer
            Gatherer.Integrator.ofGreedy((state, element, downstream) -> {
                if (!state.seen || !Objects.equals(state.value, element)) {
                    state.value = element;
                    state.seen = true;
                    return downstream.push(element);    // forward the element
                }
                return true;                            // skip it, keep consuming
            }));
    }

    public static void main(String[] args) {
        List<Integer> out = Stream.of(1, 1, 2, 2, 2, 1, 3, 3)
            .gather(dropConsecutiveDuplicates())
            .toList();
        System.out.println(out);                        // expected: [1, 2, 1, 3]
    }
}

