import java.io.*;
import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Fx {
    @FunctionalInterface
    interface IOFunction<T, R> { R apply(T t) throws IOException; }

    /** Adapts a throwing function into a plain Function that wraps the checked exception. */
    static <T, R> Function<T, R> unchecked(IOFunction<T, R> f) {
        return t -> {
            try { return f.apply(t); }
            catch (IOException e) { throw new UncheckedIOException(e); }
        };
    }

    static int readLength(String name) throws IOException {
        if (name.startsWith("missing")) throw new FileNotFoundException(name);
        return name.length();
    }

    sealed interface Result<T> {
        record Ok<T>(T value) implements Result<T> {}
        record Fail<T>(String error) implements Result<T> {}
    }

    static Result<Integer> attempt(String name) {
        try { return new Result.Ok<>(readLength(name)); }
        catch (IOException e) { return new Result.Fail<>(e.getMessage()); }
    }

    static String describe(Result<Integer> r) {
        return switch (r) {
            case Result.Ok<Integer>(var v) -> "ok " + v;
            case Result.Fail<Integer>(var msg) -> "failed: " + msg;
        };
    }

    public static void main(String[] args) {
        List<String> names = List.of("a.txt", "bb.txt", "missing.txt", "c.txt");

        try {
            names.stream().map(unchecked(Fx::readLength)).forEach(System.out::println);
        } catch (UncheckedIOException e) {
            System.out.println("stopped: " + e.getCause());
        }

        List<Result<Integer>> results = names.stream().map(Fx::attempt).toList();
        results.forEach(r -> System.out.println(describe(r)));
        System.out.println("total of successes = " + results.stream()
            .flatMap(r -> r instanceof Result.Ok<Integer> ok
                ? Stream.of(ok.value()) : Stream.<Integer>empty())
            .mapToInt(Integer::intValue).sum());
    }
}

import java.util.List;
import java.util.Optional;

public class Style {
    static Optional<String> loop(List<String> names) {
        for (String n : names) {
            if (n.length() > 4) {
                return Optional.of(n.toUpperCase());
            }
        }
        return Optional.empty();
    }

    static Optional<String> stream(List<String> names) {
        return names.stream().filter(n -> n.length() > 4).findFirst().map(String::toUpperCase);
    }

    public static void main(String[] args) {
        List<String> names = List.of("Ann", "Charlotte", "Raj", "Benjamin");
        System.out.println(loop(names));
        System.out.println(stream(names));
    }
}
